#include "udp_image_codec.h"
#include <opencv2/opencv.hpp>
#include <algorithm>
#include <cctype>
#include <cstdio>
#include <filesystem>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
namespace fs=std::filesystem;using affinecodec::Decoder;using affinecodec::Encoder;using affinecodec::PatchData;using affinecodec::u_char;
static bool isImageFile(const fs::path&p){std::string e=p.extension().string();std::transform(e.begin(),e.end(),e.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return e==".jpg"||e==".jpeg"||e==".png"||e==".bmp"||e==".tif"||e==".tiff";}
static std::vector<fs::path> listImages(const fs::path&dir){std::vector<fs::path>f;for(const auto&e:fs::directory_iterator(dir))if(e.is_regular_file()&&isImageFile(e.path()))f.push_back(e.path());std::sort(f.begin(),f.end());return f;}
static double colorMae(const cv::Mat&a,const cv::Mat&b){if(a.empty()||b.empty()||a.size()!=b.size()||a.type()!=b.type())return 0.0;cv::Mat d;cv::absdiff(a,b,d);const cv::Scalar m=cv::mean(d);double s=0;for(int c=0;c<a.channels();++c)s+=m[c];return s/a.channels();}
static cv::Mat addLabel(const cv::Mat&image,const std::string&t,const std::string&i){cv::Mat o=image.clone();if(o.channels()==1)cv::cvtColor(o,o,cv::COLOR_GRAY2BGR);cv::rectangle(o,cv::Rect(0,0,o.cols,std::min(52,o.rows)),cv::Scalar(0,0,0),cv::FILLED);cv::putText(o,t,{10,21},cv::FONT_HERSHEY_SIMPLEX,.55,{255,255,255},1,cv::LINE_AA);cv::putText(o,i,{10,43},cv::FONT_HERSHEY_SIMPLEX,.43,{255,255,255},1,cv::LINE_AA);return o;}
int main(int argc,char**argv){if(argc>5){std::cerr<<"Usage: codec_test [image-folder] [output-folder] [jpeg-bytes] [key-period]\n";return 2;}const fs::path in=argc>1?fs::path(argv[1]):fs::path("local-data/frames");const fs::path out=argc>2?fs::path(argv[2]):fs::path("output/codec");const int jpeg_bytes=argc>3?std::stoi(argv[3]):40000;const int key_period=argc>4?std::stoi(argv[4]):5;if(!fs::exists(in)){std::cerr<<"Input folder does not exist: "<<in<<'\n';return 1;}const auto files=listImages(in);if(files.empty()){std::cerr<<"No images in "<<in<<'\n';return 1;}fs::create_directories(out);std::cout<<"Input folder: "<<in<<'\n'<<"Output folder: "<<out<<'\n'<<"Target JPEG bytes: "<<jpeg_bytes<<'\n'<<"Keyframe period: "<<key_period<<'\n'<<"Max packet bytes: "<<affinecodec::kMaxUdpPacketBytes<<'\n'<<"Number of images: "<<files.size()<<"\n\n";Encoder enc;Decoder dec;std::vector<u_char>current_jpeg;std::size_t total_bytes=0,total_packets=0;for(std::size_t i=0;i<files.size();++i){cv::Mat original=cv::imread(files[i].string(),cv::IMREAD_COLOR);if(original.empty())continue;enc.pushImage(original,jpeg_bytes,key_period);cv::Mat decoded;bool produced=false,key=false;std::size_t frame_bytes=0,frame_packets=0;std::vector<u_char>chunk;while(enc.getNextChunk(chunk)){++frame_packets;++total_packets;frame_bytes+=chunk.size();total_bytes+=chunk.size();if(chunk.size()>affinecodec::kMaxUdpPacketBytes){std::cerr<<"ERROR: packet "<<chunk.size()<<" B exceeds codec limit\n";return 3;}dec.pushData(chunk);std::vector<u_char>new_jpeg;if(dec.updateKeyframe(new_jpeg)){current_jpeg=std::move(new_jpeg);dec.render(decoded,{},current_jpeg);produced=!decoded.empty();key=true;}std::vector<PatchData>patch;while(dec.getNextPatch(patch)){dec.render(decoded,patch,current_jpeg);produced=!decoded.empty();key=false;}}if(!produced){std::cout<<std::setw(4)<<i<<"  no decoded frame  "<<frame_packets<<" packets  "<<frame_bytes<<" B\n";continue;}if(decoded.channels()==1)cv::cvtColor(decoded,decoded,cv::COLOR_GRAY2BGR);if(decoded.size()!=original.size())cv::resize(decoded,decoded,original.size());const double mae=colorMae(original,decoded);const std::string oi="frame "+std::to_string(i)+"  "+files[i].filename().string();const std::string di=std::string(key?"KEY  ":"PATCH  ")+std::to_string(frame_packets)+" pkt  "+std::to_string(frame_bytes)+" B  MAE="+cv::format("%.2f",mae);cv::Mat left=addLabel(original,"ORIGINAL",oi),right=addLabel(decoded,"DECODED",di),side;cv::hconcat(left,right,side);char name[64];std::snprintf(name,sizeof(name),"%04zu.jpg",i);cv::imwrite((out/name).string(),side,{cv::IMWRITE_JPEG_QUALITY,95});std::cout<<std::setw(4)<<i<<(key?"  KEY   ":"  PATCH ")<<std::setw(3)<<frame_packets<<" pkt  "<<std::setw(7)<<frame_bytes<<" B  MAE="<<std::fixed<<std::setprecision(2)<<mae<<'\n';}std::cout<<"\nOutput: "<<out<<'\n'<<"Total codec packets: "<<total_packets<<'\n'<<"Total codec bytes: "<<total_bytes<<'\n'<<"Every getNextChunk() result is <= "<<affinecodec::kMaxUdpPacketBytes<<" bytes.\n";return 0;}
